          "defaultValue": "00000000-0000-0000-0000-000000000000",
          "type": "String",
          "metadata": {
            "schemaName": "contoso_GraphClientId"
          }
        },
        "GraphClientSecret (contoso_GraphClientSecret)": {
          "defaultValue": "",
          "type": "String",
          "metadata": {
            "schemaName": "contoso_GraphClientSecret"
          }
        },
        "GovernanceMailbox (contoso_GovernanceMailbox)": {
          "defaultValue": "governance@contoso.example",
          "type": "String",
          "metadata": {
            "schemaName": "contoso_GovernanceMailbox"
          }
        }
      },
      "triggers": {
        "First_day_of_month": {
          "type": "Recurrence",
          "recurrence": {
            "frequency": "Month",
            "interval": 1,
            "schedule": {
              "monthDays": [
                1
              ],
              "hours": [
                "5"
              ],
              "minutes": [
                0
              ]
            },
            "timeZone": "UTC"
          }
        }
      },
      "actions": {
        "List_guests": {
          "type": "Http",
          "runAfter": {},
          "inputs": {
            "method": "GET",
